result = []
for row in table_stats:
    if row["row_count"] == 0:
        mode = "full"
    elif row["row_count"] >= 1_000_000:
        mode = "large_incremental"
    else:
        mode = "incremental"
    result.append({"table_name": row["table_name"], "row_count": row["row_count"], "mode": mode})
display(result)

